  "credit-card-payoff": {
    slug: "credit-card-payoff",
    category: "finance",
    name: "Credit Card Payoff & Interest Snowball Calculator",
    description: "Calculate exact debt-free payoff timelines, total compound interest charges, and monthly payment requirements for high-interest revolving credit.",
    formula_display: "Months to Pay Off = -ln[1 - (P \u00b7 i / M)] / ln(1 + i)",
    fields: [
      {
            "id": "cc_balance",
            "label": "Credit Card Balance",
            "default": 14000,
            "prefix": "$",
            "min": 500,
            "max": 100000,
            "step": 500,
            "hint": "Total balance on card"
      },
      {
            "id": "cc_apr",
            "label": "Annual Percentage Rate (APR)",
            "default": 24.5,
            "suffix": "%",
            "min": 10,
            "max": 36,
            "step": 0.5,
            "hint": "Revolving interest rate"
      },
      {
            "id": "monthly_pay",
            "label": "Monthly Payment Plan",
            "default": 500,
            "prefix": "$",
            "min": 50,
            "max": 5000,
            "step": 50,
            "hint": "Fixed monthly cash dedicated to card"
      }
],
    metrics: [
      {
            "id": "payoff_months",
            "label": "Time to Debt Freedom",
            "default_display": "39 months (3.3 yrs)",
            "highlight": true
      },
      {
            "id": "total_cc_interest",
            "label": "Total Interest Accrued",
            "default_display": "$5,482.00"
      },
      {
            "id": "total_cc_paid",
            "label": "Total Principal + Interest Paid",
            "default_display": "$19,482.00"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const B = getNum('cc_balance');
          const i = (getNum('cc_apr') / 100) / 12;
          const M = getNum('monthly_pay');

          if (M <= B * i) {
            setDisp('payoff_months', 'Never (Under-funded)');
            setDisp('total_cc_interest', 'Infinite');
            setDisp('total_cc_paid', 'Infinite');
          } else {
            const n = -Math.log(1 - (B * i) / M) / Math.log(1 + i);
            const total = M * n;
            const interest = total - B;
            const yrs = (n / 12).toFixed(1);
            setDisp('payoff_months', Math.ceil(n) + ' mos (' + yrs + ' yrs)');
            setDisp('total_cc_interest', '$' + Math.round(interest).toLocaleString());
            setDisp('total_cc_paid', '$' + Math.round(total).toLocaleString());
          }
    }
  },
