  "wire-gauge-drop": {
    slug: "wire-gauge-drop",
    category: "construction",
    name: "Voltage Drop & Wire Gauge (AWG) Calculator",
    description: "Calculate electrical voltage drop, percentage loss, and proper American Wire Gauge (AWG) conductor sizing for single-phase copper circuits.",
    formula_display: "Voltage Drop (VD) = [2 \u00d7 K \u00d7 I \u00d7 Length (ft)] / Circular Mils (CM)",
    fields: [
      {
            "id": "circuit_voltage",
            "label": "Circuit Voltage",
            "default": 120,
            "suffix": "volts",
            "min": 12,
            "max": 480,
            "step": 12,
            "hint": "120V standard branch circuit, 240V for heavy equipment"
      },
      {
            "id": "load_amperes",
            "label": "Continuous Load Amperage",
            "default": 16,
            "suffix": "amps",
            "min": 1,
            "max": 200,
            "step": 1,
            "hint": "16A continuous on a 20A breaker (80% rule)"
      },
      {
            "id": "one_way_distance",
            "label": "One-Way Conductor Length",
            "default": 100,
            "suffix": "ft",
            "min": 10,
            "max": 1000,
            "step": 10,
            "hint": "Distance from panel to load"
      },
      {
            "id": "wire_gauge",
            "label": "Wire Gauge (12 for 12AWG, 10 for 10AWG)",
            "default": 12,
            "suffix": "AWG",
            "min": 0,
            "max": 14,
            "step": 2,
            "hint": "14 AWG (15A), 12 AWG (20A), 10 AWG (30A), 8 AWG (50A)"
      }
],
    metrics: [
      {
            "id": "voltage_drop_volts",
            "label": "Total Voltage Drop",
            "default_display": "6.35 Volts",
            "highlight": true
      },
      {
            "id": "percentage_drop",
            "label": "Percentage Voltage Drop",
            "default_display": "5.29%",
            "highlight": true
      },
      {
            "id": "voltage_at_load",
            "label": "Voltage Delivered to Load",
            "default_display": "113.65 Volts"
      },
      {
            "id": "nec_compliance",
            "label": "NEC Rec. (<3% Branch Limit)",
            "default_display": "Fails 3% limit (Upsize to 10 AWG)"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const V = getNum('circuit_voltage');
          const I = getNum('load_amperes');
          const L = getNum('one_way_distance');
          const awg = getNum('wire_gauge');

          const cmTable = { 14: 4110, 12: 6530, 10: 10380, 8: 16510, 6: 26240, 4: 41740, 2: 66360, 0: 105600 };
          const cm = cmTable[awg] || 6530;
          const k = 12.9; // copper resistance constant
          const vd = (2 * k * I * L) / cm;
          const pct = (vd / V) * 100;
          const vLoad = V - vd;

          setDisp('voltage_drop_volts', vd.toFixed(2) + ' Volts');
          setDisp('percentage_drop', pct.toFixed(2) + '%');
          setDisp('voltage_at_load', vLoad.toFixed(2) + ' Volts');
          setDisp('nec_compliance', pct <= 3.0 ? 'Compliant (< 3% NEC limit)' : 'Exceeds 3% limit (Upsize wire gauge)');
    }
  },
