  "bmr": {
    slug: "bmr",
    category: "health",
    name: "Basal Metabolic Rate (BMR) Calculator",
    description: "Calculate daily basal calories burned at rest using the clinically validated Mifflin-St Jeor and Harris-Benedict equations.",
    formula_display: "BMR (men) = 10W + 6.25H - 5A + 5 | BMR (women) = 10W + 6.25H - 5A - 161",
    fields: [
      {
            "id": "weight_lbs",
            "label": "Body Weight",
            "default": 175,
            "suffix": "lbs",
            "min": 70,
            "max": 500,
            "step": 1,
            "hint": "Current body weight in pounds"
      },
      {
            "id": "height_in",
            "label": "Height",
            "default": 70,
            "suffix": "in",
            "min": 48,
            "max": 90,
            "step": 1,
            "hint": "Height in inches (e.g. 5'10\" = 70 in)"
      },
      {
            "id": "age_years",
            "label": "Age",
            "default": 32,
            "suffix": "yrs",
            "min": 15,
            "max": 100,
            "step": 1,
            "hint": "Age in years"
      },
      {
            "id": "gender_factor",
            "label": "Biological Sex (1 for Male, 0 for Female)",
            "default": 1,
            "min": 0,
            "max": 1,
            "step": 1,
            "hint": "1 for Male (+5), 0 for Female (-161)"
      }
],
    metrics: [
      {
            "id": "bmr_calories",
            "label": "Basal Metabolic Rate",
            "default_display": "1,774 kcal/day",
            "highlight": true
      },
      {
            "id": "sedentary_burn",
            "label": "Sedentary TDEE (1.2\u00d7)",
            "default_display": "2,129 kcal/day"
      },
      {
            "id": "hourly_burn",
            "label": "Resting Hourly Burn",
            "default_display": "73.9 kcal/hr"
      },
      {
            "id": "harris_benedict",
            "label": "Harris-Benedict Equivalent",
            "default_display": "1,812 kcal/day"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const wLbs = getNum('weight_lbs');
          const hIn = getNum('height_in');
          const age = getNum('age_years');
          const isMale = getNum('gender_factor') === 1;

          const wKg = wLbs / 2.20462;
          const hCm = hIn * 2.54;
          const s = isMale ? 5 : -161;
          const bmr = (10 * wKg) + (6.25 * hCm) - (5 * age) + s;
          const sed = bmr * 1.2;
          const hr = bmr / 24;

          const hb = isMale ? 
            (66.5 + (13.75 * wKg) + (5.003 * hCm) - (6.75 * age)) :
            (655.1 + (9.563 * wKg) + (1.850 * hCm) - (4.676 * age));

          setDisp('bmr_calories', Math.round(bmr).toLocaleString() + ' kcal/day');
          setDisp('sedentary_burn', Math.round(sed).toLocaleString() + ' kcal/day');
          setDisp('hourly_burn', hr.toFixed(1) + ' kcal/hr');
          setDisp('harris_benedict', Math.round(hb).toLocaleString() + ' kcal/day');
    }
  },
