  "ellipse": {
    slug: "ellipse",
    category: "geometry",
    name: "Ellipse Area, Perimeter & Eccentricity Calculator",
    description: "Calculate exact ellipse area, Ramanujan high-precision perimeter approximation, semi-axes, focal distance, and orbital eccentricity.",
    formula_display: "Area = \u03c0 \u00b7 a \u00b7 b | Perimeter \u2248 \u03c0(a + b)[1 + 3h / (10 + \u221a(4 - 3h))], where h = (a - b)\u00b2 / (a + b)\u00b2",
    fields: [
      {
            "id": "semi_major",
            "label": "Semi-Major Axis (a)",
            "default": 10,
            "suffix": "units",
            "min": 0.1,
            "max": 1000,
            "step": 0.5,
            "hint": "Half the longest diameter"
      },
      {
            "id": "semi_minor",
            "label": "Semi-Minor Axis (b)",
            "default": 6,
            "suffix": "units",
            "min": 0.1,
            "max": 1000,
            "step": 0.5,
            "hint": "Half the shortest diameter (b \u2264 a)"
      }
],
    metrics: [
      {
            "id": "ellipse_area",
            "label": "Exact Ellipse Area",
            "default_display": "188.4956 units\u00b2",
            "highlight": true
      },
      {
            "id": "ramanujan_perimeter",
            "label": "Perimeter (Ramanujan II)",
            "default_display": "51.0540 units",
            "highlight": true
      },
      {
            "id": "linear_eccentricity",
            "label": "Focal Distance (c = \u221a(a\u00b2 - b\u00b2))",
            "default_display": "8.0000 units"
      },
      {
            "id": "first_eccentricity",
            "label": "Orbital Eccentricity (e = c/a)",
            "default_display": "0.8000 (Elliptic)"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
let a = getNum('semi_major');
          let b = getNum('semi_minor');
          if (b > a) { const tmp = a; a = b; b = tmp; }

          const area = Math.PI * a * b;
          const h = Math.pow(a - b, 2) / Math.pow(a + b, 2);
          const perim = Math.PI * (a + b) * (1 + (3 * h) / (10 + Math.sqrt(4 - (3 * h))));
          const c = Math.sqrt(Math.max(0, Math.pow(a, 2) - Math.pow(b, 2)));
          const e = a > 0 ? (c / a) : 0;

          setDisp('ellipse_area', area.toFixed(4) + ' units²');
          setDisp('ramanujan_perimeter', perim.toFixed(4) + ' units');
          setDisp('linear_eccentricity', c.toFixed(4) + ' units');
          setDisp('first_eccentricity', e.toFixed(4) + (e === 0 ? ' (Circle)' : ' (Elliptic)'));
    }
  },
