  "projectile-motion": {
    slug: "projectile-motion",
    category: "physics",
    name: "Projectile Motion & Ballistic Trajectory Calculator",
    description: "Calculate ballistic flight trajectory, maximum apogee height, total hang time, and horizontal ground range under gravitational acceleration.",
    formula_display: "Range R = [v\u2080\u00b2 \u00b7 sin(2\u03b8)] / g | Max Height H = [v\u2080\u00b2 \u00b7 sin\u00b2(\u03b8)] / (2g)",
    fields: [
      {
            "id": "velocity_v0",
            "label": "Initial Launch Velocity (v\u2080)",
            "default": 45,
            "suffix": "m/s",
            "min": 1,
            "max": 5000,
            "step": 1,
            "hint": "Muzzle or launch velocity in meters per second"
      },
      {
            "id": "launch_angle",
            "label": "Launch Angle (\u03b8)",
            "default": 45,
            "suffix": "degrees",
            "min": 1,
            "max": 89,
            "step": 1,
            "hint": "Angle above horizontal (45\u00b0 maximizes range in vacuum)"
      },
      {
            "id": "initial_height",
            "label": "Initial Release Height (y\u2080)",
            "default": 0,
            "suffix": "meters",
            "min": 0,
            "max": 1000,
            "step": 1,
            "hint": "Elevation of launch platform above ground"
      }
],
    metrics: [
      {
            "id": "max_range",
            "label": "Total Horizontal Range",
            "default_display": "206.42 meters",
            "highlight": true
      },
      {
            "id": "max_height",
            "label": "Maximum Altitude (Apogee)",
            "default_display": "51.61 meters",
            "highlight": true
      },
      {
            "id": "flight_time",
            "label": "Total Hang Time",
            "default_display": "6.49 seconds"
      },
      {
            "id": "impact_velocity",
            "label": "Terminal Impact Velocity",
            "default_display": "45.00 m/s (162.0 km/h)"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const v0 = getNum('velocity_v0');
          const deg = getNum('launch_angle');
          const y0 = getNum('initial_height');
          const g = 9.80665;

          const rad = (deg * Math.PI) / 180;
          const vx = v0 * Math.cos(rad);
          const vy = v0 * Math.sin(rad);

          // Quadratic formula for flight time: -0.5*g*t^2 + vy*t + y0 = 0
          const a = -0.5 * g;
          const b = vy;
          const c = y0;
          const disc = Math.pow(b, 2) - (4 * a * c);
          const t = (-b - Math.sqrt(Math.max(0, disc))) / (2 * a);

          const range = vx * t;
          const hMax = y0 + (Math.pow(vy, 2) / (2 * g));
          const vyImpact = vy - (g * t);
          const vImpact = Math.sqrt(Math.pow(vx, 2) + Math.pow(vyImpact, 2));

          setDisp('max_range', range.toFixed(2) + ' meters (' + (range * 3.28084).toFixed(1) + ' ft)');
          setDisp('max_height', hMax.toFixed(2) + ' meters (' + (hMax * 3.28084).toFixed(1) + ' ft)');
          setDisp('flight_time', t.toFixed(2) + ' seconds');
          setDisp('impact_velocity', vImpact.toFixed(2) + ' m/s (' + (vImpact * 3.6).toFixed(1) + ' km/h)');
    }
  },
