  "brake-stopping-distance": {
    slug: "brake-stopping-distance",
    category: "physics",
    name: "Vehicle Braking & Stopping Distance Physics Calculator",
    description: "Calculate total stopping distance in feet from initial speed, driver perception-reaction time, and road friction coefficient (dry, wet, snow, ice).",
    formula_display: "Stopping Distance = (Speed \u00d7 Reaction Time) + (Speed\u00b2 / [2 \u00d7 g \u00d7 Friction Coefficient \u03bc])",
    fields: [
      {
            "id": "vehicle_speed_mph_brake",
            "label": "Initial Vehicle Speed (MPH)",
            "default": 65,
            "suffix": "MPH",
            "min": 10,
            "max": 160,
            "step": 5,
            "hint": "Speed prior to emergency braking"
      },
      {
            "id": "reaction_time_sec",
            "label": "Driver Perception-Reaction Time",
            "default": 1.5,
            "suffix": "seconds",
            "min": 0.5,
            "max": 4.0,
            "step": 0.1,
            "hint": "AASHTO standard reaction time: 1.5 - 2.5 sec"
      },
      {
            "id": "road_surface_friction",
            "label": "Road Surface Friction (0.80 Dry, 0.50 Wet, 0.20 Snow, 0.10 Ice)",
            "default": 0.8,
            "min": 0.05,
            "max": 1.1,
            "step": 0.05,
            "hint": "Coefficient of friction \u03bc"
      }
],
    metrics: [
      {
            "id": "total_stopping_distance",
            "label": "Total Stopping Distance",
            "default_display": "319.4 feet",
            "highlight": true
      },
      {
            "id": "reaction_distance_feet",
            "label": "Distance Traveled Before Brakes Applied",
            "default_display": "143.0 feet",
            "highlight": true
      },
      {
            "id": "pure_braking_distance",
            "label": "Pure Mechanical Braking Distance",
            "default_display": "176.4 feet",
            "highlight": true
      },
      {
            "id": "car_lengths_equivalent",
            "label": "Equivalent Car Lengths (15 ft/car)",
            "default_display": "21.3 Car Lengths"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const mph = getNum('vehicle_speed_mph_brake');
          const tReact = getNum('reaction_time_sec');
          const mu = getNum('road_surface_friction') || 0.8;

          const vFps = mph * 1.466667;
          const dReact = vFps * tReact;
          const g = 32.174;
          const dBrake = Math.pow(vFps, 2) / (2 * g * mu);
          const dTotal = dReact + dBrake;

          setDisp('total_stopping_distance', dTotal.toFixed(1) + ' feet');
          setDisp('reaction_distance_feet', dReact.toFixed(1) + ' feet');
          setDisp('pure_braking_distance', dBrake.toFixed(1) + ' feet');
          setDisp('car_lengths_equivalent', (dTotal / 15).toFixed(1) + ' Car Lengths');
    }
  },
