  "internal-rate-of-return": {
    slug: "internal-rate-of-return",
    category: "finance",
    name: "Commercial Real Estate IRR & Equity Multiple Calculator",
    description: "Calculate commercial property Internal Rate of Return (IRR), Equity Multiple (EM), and multi-year cash flow yield including disposition sale proceeds.",
    formula_display: "NPV = \u2211 [CF_t / (1 + IRR)^t] = 0 | Equity Multiple = Total Cash Distributions / Total Equity Invested",
    fields: [
      {
            "id": "initial_equity_invested",
            "label": "Initial Equity Invested (Year 0)",
            "default": 500000,
            "prefix": "$",
            "min": 10000,
            "max": 100000000,
            "step": 25000,
            "hint": "Total out-of-pocket LP/GP equity down payment"
      },
      {
            "id": "annual_cash_flow_avg",
            "label": "Average Annual Operating Cash Flow",
            "default": 42000,
            "prefix": "$",
            "min": 0,
            "max": 20000000,
            "step": 5000,
            "hint": "Net operating cash distribution to equity"
      },
      {
            "id": "hold_period_years",
            "label": "Investment Hold Period (Years)",
            "default": 5,
            "suffix": "years",
            "min": 2,
            "max": 15,
            "step": 1,
            "hint": "Projected asset hold duration"
      },
      {
            "id": "net_sale_proceeds",
            "label": "Net Disposition Proceeds at Sale",
            "default": 820000,
            "prefix": "$",
            "min": 10000,
            "max": 200000000,
            "step": 50000,
            "hint": "Sale price minus loan payoff, closing fees"
      }
],
    metrics: [
      {
            "id": "property_irr_result",
            "label": "Project Internal Rate of Return (IRR)",
            "default_display": "17.42% IRR",
            "highlight": true
      },
      {
            "id": "equity_multiple_em",
            "label": "Equity Multiple (EM)",
            "default_display": "2.06\u00d7",
            "highlight": true
      },
      {
            "id": "net_profit_dollar",
            "label": "Total Net Cash Profit",
            "default_display": "$530,000.00",
            "highlight": true
      },
      {
            "id": "annualized_cash_yield",
            "label": "Average Cash-on-Cash Yield",
            "default_display": "8.40% / yr"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const c0 = getNum('initial_equity_invested');
          const cfAnnual = getNum('annual_cash_flow_avg');
          const years = getNum('hold_period_years') || 5;
          const exitProceeds = getNum('net_sale_proceeds');

          const totalDistributions = (cfAnnual * years) + exitProceeds;
          const em = c0 > 0 ? (totalDistributions / c0) : 0;
          const netProfit = totalDistributions - c0;
          const avgYield = c0 > 0 ? ((cfAnnual / c0) * 100) : 0;

          // Newton-Raphson approximation for IRR
          let r = 0.15;
          for (let iter = 0; iter < 40; iter++) {
            let npv = -c0;
            let dNpv = 0;
            for (let t = 1; t <= years; t++) {
              const flow = (t === years) ? (cfAnnual + exitProceeds) : cfAnnual;
              npv += flow / Math.pow(1 + r, t);
              dNpv -= (t * flow) / Math.pow(1 + r, t + 1);
            }
            if (Math.abs(dNpv) < 1e-9) break;
            const nextR = r - (npv / dNpv);
            if (Math.abs(nextR - r) < 1e-6) {
              r = nextR;
              break;
            }
            r = nextR;
          }

          setDisp('property_irr_result', (r * 100).toFixed(2) + '% IRR');
          setDisp('equity_multiple_em', em.toFixed(2) + '×');
          setDisp('net_profit_dollar', '$' + Math.round(netProfit).toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2}));
          setDisp('annualized_cash_yield', avgYield.toFixed(2) + '% / yr');
    }
  },
