          const valuation = capRate > 0 ? (noi / capRate) : 0;

          setDisp('net_operating_income_noi', '$' + Math.round(noi).toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' / yr');
