          const valuation = capRate > 0 ? (noi / capRate) : 0;
          const perPad = pads > 0 ? (valuation / pads) : 0;

          setDisp('annual_park_noi', '$' + Math.round(noi).toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' / yr');
