  "cold-chain-mkt": {
    slug: "cold-chain-mkt",
    category: "logistics",
    name: "Cold Chain Mean Kinetic Temperature (MKT) Shelf-Life Calculator",
    description: "Calculate Mean Kinetic Temperature (MKT) across temperature excursion logs for pharmaceutical, vaccine, and perishable cold-chain logistics (USP <1150>).",
    formula_display: "MKT = (\u0394H / R) / -ln(\u03a3 e^(-\u0394H / [R \u00b7 T_k]) / n) | Activation Energy \u0394H = 83.144 kJ/mol",
    fields: [
      {
            "id": "baseline_temp_c",
            "label": "Storage Baseline Target Temp (\u00b0C)",
            "default": 5.0,
            "suffix": "\u00b0C",
            "min": -25,
            "max": 25,
            "step": 0.5,
            "hint": "Target cold room temp (typically 2\u00b0C to 8\u00b0C)"
      },
      {
            "id": "excursion_temp_c",
            "label": "Excursion Peak Temperature (\u00b0C)",
            "default": 14.5,
            "suffix": "\u00b0C",
            "min": 0,
            "max": 45,
            "step": 0.5,
            "hint": "Maximum spike during transit delay or breakdown"
      },
      {
            "id": "excursion_hours",
            "label": "Excursion Duration (Hours)",
            "default": 6.0,
            "suffix": "hours",
            "min": 0.5,
            "max": 72,
            "step": 0.5,
            "hint": "Time product remained above 8\u00b0C specification"
      },
      {
            "id": "total_transit_hours",
            "label": "Total Shipment Duration (Hours)",
            "default": 48.0,
            "suffix": "hours",
            "min": 12,
            "max": 240,
            "step": 6,
            "hint": "Total recorded data logger duration"
      }
],
    metrics: [
      {
            "id": "calculated_mkt_c",
            "label": "Mean Kinetic Temperature (MKT)",
            "default_display": "6.8\u00b0C",
            "highlight": true
      },
      {
            "id": "usp_compliance_status",
            "label": "USP <659> Regulatory Status",
            "default_display": "Compliant (Within 2\u00b0C - 8\u00b0C MKT Limit)",
            "highlight": true
      },
      {
            "id": "equivalent_thermal_stress",
            "label": "Thermal Degradation Multiplier",
            "default_display": "1.32x Baseline Degradation"
      },
      {
            "id": "calculated_mkt_f",
            "label": "MKT in Fahrenheit",
            "default_display": "44.2\u00b0F"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const tBase = getNum('baseline_temp_c');
          const tExc = getNum('excursion_temp_c');
          const excHrs = getNum('excursion_hours');
          const totHrs = getNum('total_transit_hours') || 48;

          const baseHrs = Math.max(1, totHrs - excHrs);
          const kBase = tBase + 273.15;
          const kExc = tExc + 273.15;
          const deltaH_R = 10000;

          const term1 = baseHrs * Math.exp(-deltaH_R / kBase);
          const term2 = excHrs * Math.exp(-deltaH_R / kExc);
          const avgTerm = (term1 + term2) / totHrs;
          const mktK = -deltaH_R / Math.log(avgTerm);
          const mktC = mktK - 273.15;
          const mktF = (mktC * 9/5) + 32;

          let status = 'Compliant (MKT within 2-8°C)';
          if (mktC > 8.0) {
            status = 'NON-COMPLIANT (Thermal Excursion Breach)';
          } else if (tExc > 15.0) {
            status = 'Warning: Transient Spike > 15°C';
          }

          setDisp('calculated_mkt_c', mktC.toFixed(1) + '°C');
          setDisp('usp_compliance_status', status);
          setDisp('equivalent_thermal_stress', (Math.pow(2, (mktC - tBase) / 5)).toFixed(2) + 'x Baseline Rate');
          setDisp('calculated_mkt_f', mktF.toFixed(1) + '°F');
    }
  },
