  "structured-settlement-npv": {
    slug: "structured-settlement-npv",
    category: "legal",
    name: "Structured Settlement Annuity Lump-Sum Present Value (NPV)",
    description: "Calculate fair market cash lump-sum present value (NPV) and purchasing company discount factoring haircut when selling structured settlement annuity payments.",
    formula_display: "NPV = \u03a3 [Monthly Payment / (1 + r / 12)\u1d57] | Discount Rate r typically 8% - 15%",
    fields: [
      {
            "id": "monthly_annuity_payment",
            "label": "Monthly Annuity Payment ($)",
            "default": 1750,
            "prefix": "$",
            "min": 100,
            "max": 25000,
            "step": 50,
            "hint": "Guaranteed tax-free structured settlement payment"
      },
      {
            "id": "remaining_payment_years",
            "label": "Remaining Payment Duration (Years)",
            "default": 15,
            "suffix": "yrs",
            "min": 1,
            "max": 40,
            "step": 1,
            "hint": "Years of guaranteed annuity payments remaining"
      },
      {
            "id": "purchaser_discount_rate_pct",
            "label": "Factoring Company Discount Rate (%)",
            "default": 11.5,
            "suffix": "%",
            "min": 4.0,
            "max": 25.0,
            "step": 0.5,
            "hint": "Annual discount rate quoted by settlement buyer (typically 9% - 14%)"
      }
],
    metrics: [
      {
            "id": "lump_sum_cash_offer",
            "label": "Fair Net Lump-Sum Cash Offer",
            "default_display": "$149,420.00",
            "highlight": true
      },
      {
            "id": "total_nominal_payments",
            "label": "Total Future Guaranteed Payments",
            "default_display": "$315,000.00",
            "highlight": true
      },
      {
            "id": "effective_discount_haircut",
            "label": "Discount Haircut Surrendered",
            "default_display": "52.6% Lost to Discounting ($165,580)"
      },
      {
            "id": "fair_court_benchmark",
            "label": "Judicial Approval Fairness Assessment",
            "default_display": "Reasonable Rate for Structured Buyout"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const pmt = getNum('monthly_annuity_payment');
          const yrs = getNum('remaining_payment_years');
          const disc = (getNum('purchaser_discount_rate_pct') || 11.5) / 100;

          const n = yrs * 12;
          const r = disc / 12;
          const totalNominal = pmt * n;
          const pv = r > 0 ? (pmt * (1 - Math.pow(1 + r, -n)) / r) : totalNominal;
          const haircut = totalNominal - pv;
          const haircutPct = totalNominal > 0 ? (haircut / totalNominal) * 100 : 0;

          setDisp('lump_sum_cash_offer', '$' + Math.round(pv).toLocaleString());
          setDisp('total_nominal_payments', '$' + Math.round(totalNominal).toLocaleString());
          setDisp('effective_discount_haircut', haircutPct.toFixed(1) + '% Lost ($' + Math.round(haircut).toLocaleString() + ')');
          setDisp('fair_court_benchmark', disc <= 0.12 ? 'Favorable Rate (Likely Court Approval)' : 'High Discount (Scrutiny Expected)');
    }
  },
