  "car-accident-diminished-value": {
    slug: "car-accident-diminished-value",
    category: "legal",
    name: "Car Accident Diminished Value Formula (17c Rule) Calculator",
    description: "Calculate inherent diminished value for a repaired vehicle using the Georgia Insurance Commissioner Formula 17c standard recognized nationwide.",
    formula_display: "Diminished Value = Base Loss (10% of NADA Value) \u00d7 Damage Modifier \u00d7 Mileage Modifier",
    fields: [
      {
            "id": "pre_accident_nada_value",
            "label": "Pre-Accident NADA / KBB Clean Retail Value ($)",
            "default": 34000,
            "prefix": "$",
            "min": 2500,
            "max": 250000,
            "step": 500,
            "hint": "Vehicle fair market value immediately prior to collision"
      },
      {
            "id": "damage_severity_modifier",
            "label": "Damage Severity (0.00 Minor to 1.00 Severe Structural)",
            "default": 0.5,
            "min": 0.0,
            "max": 1.0,
            "step": 0.25,
            "hint": "1.00: Severe frame, 0.75: Major structural, 0.50: Moderate, 0.25: Minor panel"
      },
      {
            "id": "vehicle_mileage",
            "label": "Vehicle Odometer Mileage",
            "default": 38000,
            "suffix": "miles",
            "min": 0,
            "max": 200000,
            "step": 2500,
            "hint": "Current odometer reading at time of accident"
      }
],
    metrics: [
      {
            "id": "calculated_diminished_value",
            "label": "Claimable Diminished Value",
            "default_display": "$1,020.00",
            "highlight": true
      },
      {
            "id": "base_loss_cap",
            "label": "Base 10% Diminution Cap",
            "default_display": "$3,400.00",
            "highlight": true
      },
      {
            "id": "mileage_deduction_modifier",
            "label": "Mileage Discount Factor",
            "default_display": "0.60 (20k - 39,999 miles)",
            "highlight": true
      },
      {
            "id": "post_repair_resale_value",
            "label": "Estimated Resale Market Value",
            "default_display": "$32,980.00"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const val = getNum('pre_accident_nada_value');
          const dmg = getNum('damage_severity_modifier');
          const mi = getNum('vehicle_mileage');

          let miMod = 1.0;
          if (mi >= 100000) miMod = 0.0;
          else if (mi >= 80000) miMod = 0.2;
          else if (mi >= 60000) miMod = 0.4;
          else if (mi >= 40000) miMod = 0.6;
          else if (mi >= 20000) miMod = 0.8;
          else miMod = 1.0;

          const baseCap = val * 0.10;
          const dv = baseCap * dmg * miMod;
          const postVal = val - dv;

          setDisp('calculated_diminished_value', '$' + Math.round(dv).toLocaleString());
          setDisp('base_loss_cap', '$' + Math.round(baseCap).toLocaleString());
          setDisp('mileage_deduction_modifier', miMod.toFixed(1) + 'x Multiplier');
          setDisp('post_repair_resale_value', '$' + Math.round(postVal).toLocaleString());
    }
  },
