  "medical-malpractice-damages-cap": {
    slug: "medical-malpractice-damages-cap",
    category: "legal",
    name: "Medical Malpractice Noneconomic Damages Cap Adjustment Calculator",
    description: "Calculate medical malpractice verdict reductions, applying state statutory noneconomic damage caps (e.g. California MICRA, Texas, Florida, Ohio).",
    formula_display: "Total Payout = Proven Economic Damages + min(Jury Noneconomic Award, Statutory Cap)",
    fields: [
      {
            "id": "economic_damages_usd",
            "label": "Proven Economic Damages ($ USD)",
            "default": 850000,
            "prefix": "$",
            "min": 50000,
            "max": 20000000,
            "step": 50000,
            "hint": "Past/future medical bills and lifetime lost wages (uncapped)"
      },
      {
            "id": "jury_noneconomic_verdict",
            "label": "Jury Noneconomic Verdict (Pain & Suffering $)",
            "default": 1500000,
            "prefix": "$",
            "min": 50000,
            "max": 50000000,
            "step": 100000,
            "hint": "Jury award for physical pain and loss of quality of life"
      },
      {
            "id": "state_statutory_cap_usd",
            "label": "State Statutory Noneconomic Cap ($)",
            "default": 350000,
            "prefix": "$",
            "min": 250000,
            "max": 1500000,
            "step": 25000,
            "hint": "California MICRA (AB 35) = $350k injury / $500k wrongful death"
      }
],
    metrics: [
      {
            "id": "final_reduced_payout_usd",
            "label": "Final Enforceable Court Judgment",
            "default_display": "$1,200,000.00",
            "highlight": true
      },
      {
            "id": "noneconomic_verdict_slashed",
            "label": "Verdict Reduction (Tort Reform Cut)",
            "default_display": "-$1,150,000.00 Slashed",
            "highlight": true
      },
      {
            "id": "effective_recovery_pct",
            "label": "Client Percentage of Jury Verdict",
            "default_display": "51.1% of Original Jury Verdict",
            "highlight": true
      },
      {
            "id": "economic_payout_uncapped",
            "label": "Economic Damages (100% Preserved)",
            "default_display": "$850,000.00"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const econ = getNum('economic_damages_usd');
          const nonEcon = getNum('jury_noneconomic_verdict');
          const cap = getNum('state_statutory_cap_usd');

          const cappedNonEcon = Math.min(nonEcon, cap);
          const finalJudg = econ + cappedNonEcon;
          const origJury = econ + nonEcon;
          const slashed = nonEcon - cappedNonEcon;
          const pct = origJury > 0 ? (finalJudg / origJury) * 100 : 100;

          setDisp('final_reduced_payout_usd', '$' + Math.round(finalJudg).toLocaleString());
          setDisp('noneconomic_verdict_slashed', (slashed > 0 ? '-$' + Math.round(slashed).toLocaleString() + ' Slashed' : '$0.00 (Under Cap)'));
          setDisp('effective_recovery_pct', pct.toFixed(1) + '% of Jury Verdict');
          setDisp('economic_payout_uncapped', '$' + Math.round(econ).toLocaleString() + ' (100% Paid)');
    }
  },
