  "dropshipping-vs-3pl-margin": {
    slug: "dropshipping-vs-3pl-margin",
    category: "ecommerce",
    name: "Dropshipping vs 3PL Warehousing Profitability Calculator",
    description: "Compare net profit margins between direct supplier dropshipping versus bulk wholesale inventory stored in a domestic 3PL fulfillment warehouse.",
    formula_display: "3PL Savings = (Dropship Unit Cost \u00d7 Volume) - [(Wholesale Unit Cost + 3PL Pick/Pack) \u00d7 Volume + Monthly Storage]",
    fields: [
      {
            "id": "monthly_fulfilled_orders",
            "label": "Monthly Order Volume",
            "default": 1800,
            "suffix": "orders",
            "min": 100,
            "max": 50000,
            "step": 50,
            "hint": "Units sold per month"
      },
      {
            "id": "dropship_unit_cost",
            "label": "Dropship Unit Supplier Price",
            "default": 24.5,
            "suffix": "$",
            "min": 2,
            "max": 500,
            "step": 0.5,
            "hint": "Total per-unit cost charged by dropshipping vendor including shipping"
      },
      {
            "id": "bulk_wholesale_unit_cogs",
            "label": "Bulk Wholesale Manufacturing Cost",
            "default": 9.2,
            "suffix": "$",
            "min": 1,
            "max": 300,
            "step": 0.5,
            "hint": "Factory price per unit when ordering in bulk container quantities"
      },
      {
            "id": "warehouse_pick_pack_per_unit",
            "label": "3PL Pick, Pack & Postage Per Order",
            "default": 7.4,
            "suffix": "$",
            "min": 2,
            "max": 35,
            "step": 0.25,
            "hint": "Fulfillment warehouse handling plus domestic postage"
      },
      {
            "id": "monthly_3pl_pallet_storage",
            "label": "Monthly 3PL Pallet Storage Total",
            "default": 450,
            "suffix": "$",
            "min": 50,
            "max": 10000,
            "step": 50,
            "hint": "Monthly pallet holding fees charged by 3PL"
      }
],
    metrics: [
      {
            "id": "net_monthly_3pl_savings",
            "label": "Monthly 3PL Net Cost Savings",
            "default_display": "$13,770 / mo",
            "highlight": true
      },
      {
            "id": "unit_margin_difference",
            "label": "Cost Savings Per Unit",
            "default_display": "$7.65 / unit",
            "highlight": true
      },
      {
            "id": "annual_3pl_profit_advantage",
            "label": "Annualized Profit Advantage",
            "default_display": "$165,240 / year",
            "highlight": true
      },
      {
            "id": "breakeven_monthly_volume",
            "label": "Volume to Justify 3PL Transition",
            "default_display": "58 Orders / Month"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const vol = getNum('monthly_fulfilled_orders');
          const dropCost = getNum('dropship_unit_cost');
          const bulkCost = getNum('bulk_wholesale_unit_cogs');
          const pickPack = getNum('warehouse_pick_pack_per_unit');
          const storage = getNum('monthly_3pl_pallet_storage');

          const totalDrop = vol * dropCost;
          const var3pl = bulkCost + pickPack;
          const total3pl = (vol * var3pl) + storage;
          const savings = totalDrop - total3pl;
          const unitSavings = vol > 0 ? (savings / vol) : 0;
          const annualSavings = savings * 12;

          const marginGap = dropCost - var3pl;
          const beVol = marginGap > 0 ? Math.ceil(storage / marginGap) : 0;

          setMetric('net_monthly_3pl_savings', '$' + Math.round(savings).toLocaleString() + ' / mo');
          setMetric('unit_margin_difference', '$' + unitSavings.toFixed(2) + ' / unit');
          setMetric('annual_3pl_profit_advantage', '$' + Math.round(annualSavings).toLocaleString() + ' / year');
          setMetric('breakeven_monthly_volume', beVol.toLocaleString() + ' Orders / Month');
    }
  },
