          const batchVal = purifiedMass * valPerG;

          setMetric('purified_bulk_protein_yield', purifiedMass.toFixed(1) + ' Grams');
          setMetric('total_crude_protein_harvest', crudeMass.toFixed(1) + ' Grams Total');
