  "maintenance-fluid-pediatric": {
    slug: "maintenance-fluid-pediatric",
    category: "biotech",
    name: "Maintenance IV Fluid Requirements (Holliday-Segar 4-2-1 Rule) Calculator",
    description: "Calculate daily and hourly maintenance IV fluid requirements for pediatric and adult patients using the standard clinical Holliday-Segar 4-2-1 methodology.",
    formula_display: "First 10 kg: 4 mL/kg/hr | Next 10 kg: 2 mL/kg/hr | Each kg > 20 kg: 1 mL/kg/hr",
    fields: [
      {
            "id": "patient_body_weight_kg",
            "label": "Patient Body Weight (kg)",
            "default": 24.0,
            "suffix": "kg",
            "min": 1.0,
            "max": 180,
            "step": 0.5,
            "hint": "Patient weight in kilograms"
      }
],
    metrics: [
      {
            "id": "hourly_maintenance_infusion_rate",
            "label": "Hourly Maintenance IV Rate",
            "default_display": "64.0 mL/hr",
            "highlight": true
      },
      {
            "id": "daily_maintenance_fluid_volume",
            "label": "24-Hour Total Maintenance Fluid",
            "default_display": "1,536 mL / Day",
            "highlight": true
      },
      {
            "id": "recommended_electrolyte_solution",
            "label": "Recommended Maintenance Solution",
            "default_display": "D5 0.9% NS + 20 mEq/L KCl",
            "highlight": true
      },
      {
            "id": "weight_tier_bracket",
            "label": "Weight Tier Classification",
            "default_display": "Tier 3 (> 20 kg Bracket)"
      }
],
    calculate: function(getNum, setMetric, setDisp, fact, nPr, fmt, acos, atan, cbrt) {
const wt = getNum('patient_body_weight_kg');

          if (wt > 0) {
            let hourly = 0;
            let tier = 'Tier 1 (≤ 10 kg Bracket)';

            if (wt <= 10) {
              hourly = wt * 4;
            } else if (wt <= 20) {
              hourly = 40 + (wt - 10) * 2;
              tier = 'Tier 2 (10 - 20 kg Bracket)';
            } else {
              hourly = 60 + (wt - 20) * 1;
              tier = 'Tier 3 (> 20 kg Bracket)';
            }

            const daily = hourly * 24;

            setMetric('hourly_maintenance_infusion_rate', hourly.toFixed(1) + ' mL/hr');
            setMetric('daily_maintenance_fluid_volume', Math.round(daily).toLocaleString() + ' mL / Day');
            setMetric('recommended_electrolyte_solution', 'D5 0.9% NS + 20 mEq/L KCl');
            setMetric('weight_tier_bracket', tier);
          }
    }
  },
